<?php
/* =========================================================
 *  Signals — server entry point (market data proxy, accounts, private paper accounts)
 *  ---------------------------------------------------------
 *  You do NOT edit this file. Your settings (Upstox analytics token, who may sign up, your runner key) live in auth-local.php,
 *  which is git-ignored: copy auth-local.example.php to auth-local.php on your server and fill it in. See SETUP-hostinger.txt.
 *  Every route except ping, the Upstox login callback and sign-up / log-in needs a logged-in person; trading and phone alerts need the owner.
 * ========================================================= */

const CACHE_DIR = __DIR__ . '/cache';

header('Content-Type: application/json; charset=utf-8');
header('Cache-Control: no-store');
header('X-Content-Type-Options: nosniff');
header('X-Frame-Options: DENY');
header('Referrer-Policy: no-referrer');

function out($code, $arr) { http_response_code($code); echo json_encode($arr); exit; }
require __DIR__ . '/auth.php';   // accounts; also loads auth-local.php (token, setup code, runner key)

if (isset($_GET['ping'])) {
    /* exchange-synced time: Upstox's own clock (a PC clock can be off by seconds, which would make a still-forming 5-minute candle look finished) */
    $now = (int)round(microtime(true) * 1000);
    $ch = curl_init('https://api.upstox.com/');
    curl_setopt_array($ch, [CURLOPT_NOBODY => true, CURLOPT_HEADER => true, CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 3]);
    $h = curl_exec($ch); curl_close($ch);
    if ($h && preg_match('/^date:\s*(.+)$/mi', $h, $m) && ($t = strtotime(trim($m[1])))) $now = $t * 1000;
    out(200, ['ok' => true, 'configured' => strpos(UPSTOX_TOKEN, 'PASTE_') !== 0, 'php' => PHP_VERSION, 'now' => $now, 'auth' => auth_public()]);
}

/* optional Upstox order connection (trade.php, OFF by default). The login redirect comes back without the PIN header, so it is checked by a one-time state instead. */
if (isset($_GET['callback'])) { require __DIR__ . '/trade.php'; trade_callback(); exit; }

/* sign-up, log-in, log-out, password, owner admin */
if (isset($_GET['auth'])) { auth_handle((string)$_GET['auth']); exit; }

/* from here on a person must be logged in (or be the owner's runner) */
$me = auth_gate(); $GLOBALS['IX_ME'] = $me;
if (isset($_GET['trade'])) { auth_gate(['admin', 'runner']); require __DIR__ . '/trade.php'; trade_handle((string)$_GET['trade']); exit; }   // real orders: the owner and the owner's runner only
if (isset($_GET['svc'])) { require __DIR__ . '/svc.php'; svc_handle((string)$_GET['svc']); exit; }
/* paper-trading account: one PRIVATE account per person, chosen by the login session only (nothing the page sends can name another account) */
if (isset($_GET['store'])) {
    if ($me['id'] === 'owner') a_adopt_legacy('owner');
    $f = a_udir($me['id']) . '/paper.php';
    if ($_SERVER['REQUEST_METHOD'] === 'POST') {
        $b = file_get_contents('php://input');
        if (strlen($b) > 3000000 || json_decode($b) === null) out(400, ['status' => 'error', 'message' => 'Bad data']);
        $new = json_decode($b, true);
        a_with_lock(function () use ($f, $b, $new) {
            /* never let a stale window undo a newer one: refuse a save that re-opens a position already closed on the server, or that is older than what is stored */
            $old = a_read($f, null);
            if (is_array($old) && isset($old['book']) && isset($new['book'])) {
                $closed = []; foreach ((array)($old['book']['hist'] ?? []) as $h) if (isset($h['id'])) $closed[$h['id']] = 1;
                foreach ((array)($new['book']['pos'] ?? []) as $p) if (isset($p['id']) && isset($closed[$p['id']])) out(409, ['status' => 'error', 'conflict' => true, 'message' => 'Stale paper account: a position you hold was already closed in another window or on the server.']);
                $nt = (int)($new['book']['ts'] ?? 0); if ($nt > 0 && (int)($old['book']['ts'] ?? 0) > $nt) out(409, ['status' => 'error', 'conflict' => true, 'message' => 'Stale paper account: a newer copy is already saved.']);
            }
            $tmp = dirname($f) . '/.w' . bin2hex(random_bytes(6)) . '.php'; file_put_contents($tmp, T_HEAD . $b, LOCK_EX); @chmod($tmp, 0600);
            if (!@rename($tmp, $f)) { file_put_contents($f, T_HEAD . $b, LOCK_EX); @unlink($tmp); }
        });
        out(200, ['status' => 'success']);
    }
    if (!is_file($f)) { echo '{}'; exit; }
    $raw = (string)file_get_contents($f); echo strpos($raw, T_HEAD) === 0 ? substr($raw, strlen(T_HEAD)) : '{}';
    exit;
}
/* the engine's own record: what the owner's 24/7 runner paper-traded, read-only for everyone (no cash or log, only trades) */
if (isset($_GET['record'])) {
    $b = a_read(a_udir('engine') . '/paper.php')['book'] ?? null;
    if (!$b) out(200, ['status' => 'success', 'record' => null]);
    out(200, ['status' => 'success', 'record' => ['since' => $b['start'] ?? null, 'ts' => $b['ts'] ?? 0, 'hist' => array_slice((array)($b['hist'] ?? []), 0, 500), 'pos' => array_map(function ($p) { return array_intersect_key($p, array_flip(['ix', 'kind', 'strike', 'type', 'entry', 'ltp', 'sl', 'slNow', 't0', 'dir', 'half'])); }, (array)($b['pos'] ?? []))]]);
}
/* free fallback: Yahoo Finance index candles (used while no Upstox token is set) */
if (isset($_GET['yahoo'])) {
    auth_rate($me['id']);
    $map = ['NIFTY' => '^NSEI', 'BANKNIFTY' => '^NSEBANK', 'SENSEX' => '^BSESN', 'VIX' => '^INDIAVIX'];
    $sym = $map[$_GET['yahoo']] ?? null;
    $iv  = $_GET['interval'] ?? '5m';
    $rg  = $_GET['range'] ?? '5d';
    if (!$sym || !in_array($iv, ['1m', '5m', '1d'], true) || !in_array($rg, ['1d', '5d', '1mo', '60d', '1y', '5y'], true)) out(400, ['status' => 'error', 'message' => 'Bad Yahoo request']);
    $ttl = $iv === '1d' ? 900 : 25;
    if (!is_dir(CACHE_DIR)) { @mkdir(CACHE_DIR, 0755, true); @file_put_contents(CACHE_DIR . '/.htaccess', "Require all denied\nDeny from all\n"); }
    $cf = CACHE_DIR . '/y_' . md5($sym . $iv . $rg) . '.json';
    if (is_file($cf) && (time() - filemtime($cf)) < $ttl) { echo file_get_contents($cf); exit; }
    $body = false; $code = 0;
    foreach (['query1', 'query2'] as $host) {
        $ch = curl_init("https://$host.finance.yahoo.com/v8/finance/chart/" . rawurlencode($sym) . "?interval=$iv&range=$rg&includePrePost=false");
        curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 15, CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_HTTPHEADER => ['Accept: application/json', 'User-Agent: Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0 Mobile Safari/537.36']]);
        $body = curl_exec($ch); $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); curl_close($ch);
        if ($code === 200 && $body) break;
    }
    if ($code !== 200 || !$body) {
        if (is_file($cf)) { echo file_get_contents($cf); exit; }   // serve last good copy
        out(502, ['status' => 'error', 'message' => 'Yahoo data unavailable (HTTP ' . $code . ')']);
    }
    @file_put_contents($cf, $body);
    echo $body;
    exit;
}
if (strpos(UPSTOX_TOKEN, 'PASTE_') === 0) {
    out(500, ['status' => 'error', 'message' => 'Upstox token not set (UPSTOX_TOKEN in auth-local.php)']);
}

/* ---------------- one Upstox token shared by everybody ----------------
   Upstox allows about 2000 requests per 30 minutes for this token, however many people use the site. So: (1) answers are cached and shared between everyone,
   (2) the live quotes request is split per instrument and each instrument is cached for a few seconds, so ten people watching the same options cost one request,
   (3) a budget guard stops asking Upstox before the allowance is used up and serves the last good answer instead. */
defined('UPSTREAM_PER_30MIN') || define('UPSTREAM_PER_30MIN', getenv('SIGNALS_TEST_BUDGET') ? (int)getenv('SIGNALS_TEST_BUDGET') : 1700);
defined('UPSTREAM_PER_MIN') || define('UPSTREAM_PER_MIN', 380);
$UP = getenv('SIGNALS_TEST_DATA_UPSTREAM') ?: 'https://api.upstox.com';
function ix_budget($note = false) {   // true while there is allowance left; $note = count one more request
    $h = fopen(ix_data_dir() . '/upstream.cnt', 'c+'); if (!$h) return true; flock($h, LOCK_EX);
    $b = json_decode((string)stream_get_contents($h), true); if (!is_array($b)) $b = []; $now = time(); $m = (int)floor($now / 60);
    foreach ($b as $k => $v) if ((int)$k < $m - 31) unset($b[$k]);
    $total = array_sum($b); $thisMin = (int)($b[$m] ?? 0); $ok = $total < UPSTREAM_PER_30MIN && $thisMin < UPSTREAM_PER_MIN;
    if ($note) { $b[$m] = $thisMin + 1; ftruncate($h, 0); rewind($h); fwrite($h, json_encode($b)); }
    flock($h, LOCK_UN); fclose($h); return $ok;
}
function ix_fetch($url) {
    $ch = curl_init($url);
    curl_setopt_array($ch, [CURLOPT_RETURNTRANSFER => true, CURLOPT_TIMEOUT => 20, CURLOPT_HTTPHEADER => ['Accept: application/json', 'Authorization: Bearer ' . UPSTOX_TOKEN]]);
    $body = curl_exec($ch); $code = curl_getinfo($ch, CURLINFO_HTTP_CODE); $err = curl_error($ch); curl_close($ch);
    return [$body, $code, $err];
}
if (!is_dir(CACHE_DIR)) { @mkdir(CACHE_DIR, 0755, true); @file_put_contents(CACHE_DIR . '/.htaccess', "Require all denied\nDeny from all\n"); }

auth_rate($me['id']);   // every request to the data proxy counts, valid or not
$path = $_GET['path'] ?? '';
$allowed = ['/v2/instruments/search', '/v3/historical-candle/', '/v2/option/chain', '/v2/option/contract', '/v2/market-quote/quotes'];
$ok = false;
foreach ($allowed as $p) { if (strpos($path, $p) === 0) { $ok = true; break; } }
if (!$ok || strpos($path, '..') !== false || !preg_match('#^/v[23]/[A-Za-z0-9_\-/%|:.]+$#', $path)) {
    out(400, ['status' => 'error', 'message' => 'Path not allowed']);
}

$params = $_GET;
unset($params['path']);

/* live quotes: cached per instrument for a few seconds, only the missing ones go to Upstox */
if ($path === '/v2/market-quote/quotes' && isset($params['instrument_key'])) {
    $keys = array_values(array_unique(array_filter(array_map('trim', explode(',', (string)$params['instrument_key'])))));
    if (!$keys || count($keys) > 120) out(400, ['status' => 'error', 'message' => 'Between 1 and 120 instruments']);
    foreach ($keys as $k) if (!preg_match('/^[A-Za-z0-9_|: .&\-]{3,80}$/', $k)) out(400, ['status' => 'error', 'message' => 'Bad instrument key']);
    $data = []; $miss = []; $ttl = 4;
    foreach ($keys as $k) {
        $f = CACHE_DIR . '/q_' . md5($k) . '.json';
        if (is_file($f) && time() - filemtime($f) < $ttl && ($e = json_decode((string)file_get_contents($f), true))) { $data[$e['token']] = $e['entry']; continue; }
        $miss[] = $k;
    }
    if ($miss) {
        $res = null;
        if (ix_budget()) {
            [$body, $code, $err] = ix_fetch($UP . '/v2/market-quote/quotes?instrument_key=' . rawurlencode(implode(',', $miss))); ix_budget(true);
            if ($code === 200 && ($j = json_decode((string)$body, true)) && is_array($j['data'] ?? null)) {
                foreach ($j['data'] as $entry) { $tok = (string)($entry['instrument_token'] ?? ''); if ($tok === '') continue; $data[$tok] = $entry; @file_put_contents(CACHE_DIR . '/q_' . md5($tok) . '.json', json_encode(['token' => $tok, 'entry' => $entry])); }
                $res = true;
            }
        }
        if (!$res) {   // allowance used up or Upstox failed: the last good price (at most 2 minutes old) is better than nothing
            foreach ($miss as $k) { $f = CACHE_DIR . '/q_' . md5($k) . '.json'; if (is_file($f) && time() - filemtime($f) < 120 && ($e = json_decode((string)file_get_contents($f), true))) { $data[$e['token']] = $e['entry']; header('X-Stale: quotes'); } }
            if (!$data) out(503, ['status' => 'error', 'message' => 'Live prices are paused for a moment (shared data allowance). Try again shortly.']);
        }
    }
    out(200, ['status' => 'success', 'data' => $data]);
}

$url = $UP . str_replace('|', '%7C', $path) . ($params ? '?' . http_build_query($params) : '');

/* cache: search 30 days, contracts 6 h, option chain 20 s, daily 30 min, 5m history 10 min, today's intraday 45 s */
if (strpos($path, '/v2/instruments/search') === 0)             $ttl = 2592000;
elseif (strpos($path, '/v2/option/contract') === 0)            $ttl = 21600;
elseif (strpos($path, '/v2/option/chain') === 0)               $ttl = 20;
elseif (strpos($path, '/v2/market-quote/') === 0)              $ttl = 3;
elseif (strpos($path, '/v3/historical-candle/intraday/') === 0) $ttl = 45;
elseif (strpos($path, '/days/') !== false)                     $ttl = 1800;
else                                                           $ttl = 600;

$cf = CACHE_DIR . '/' . md5($url) . '.json';
if (is_file($cf) && (time() - filemtime($cf)) < $ttl) {
    echo file_get_contents($cf);
    exit;
}
$staleOk = is_file($cf) && (time() - filemtime($cf)) < 900;   // an answer up to 15 minutes old beats an error

if (!ix_budget()) {
    if ($staleOk) { header('X-Stale: budget'); echo file_get_contents($cf); exit; }
    out(503, ['status' => 'error', 'message' => 'The shared market-data allowance is used up for a few minutes. Try again shortly.']);
}
[$body, $code, $err] = ix_fetch($url); ix_budget(true);

if ($body === false) { if ($staleOk) { header('X-Stale: error'); echo file_get_contents($cf); exit; } out(502, ['status' => 'error', 'message' => 'Upstox unreachable: ' . $err]); }
if ($code === 200) @file_put_contents($cf, $body);
elseif ($staleOk && in_array($code, [429, 500, 502, 503, 504], true)) { header('X-Stale: error'); echo file_get_contents($cf); exit; }
http_response_code($code ?: 502);
echo $body;
